//! The Munsell renotation data (Newhall, Nickerson & Judd, 1943) -
//! the real, within-MacAdam-limits colors of the original article.
//!
//! Source dataset: colour-science/colour
//! (`colour/notation/datasets/munsell/real.py`).
//!
//! The chromaticities assume CIE illuminant C; the published
//! luminance factors are scaled by `1/0.975` relative to a perfect
//! diffuser and are stored here multiplied by `0.975`, i.e. as true
//! luminance `Y`.

use crate::Color;
use crate::Hue;
use crate::Xyz;

/// A single Munsell renotation sample: one `H V/C` specification
/// with its measured CIE `xyY` (illuminant C) value.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct MunsellSample {
    /// The hue notation (`"2.5R"` .. `"10RP"`).
    pub hue: &'static str,
    /// The position of the hue on the Munsell hue circle
    /// (`0.0` = 2.5R, increasing by 9 degrees per step,
    /// `"10RP"` = 39.0).
    pub hue_number: f64,
    /// The Munsell value (`1.0` - `9.0`, neutral 0-10 scale).
    pub value: f64,
    /// The Munsell chroma (`2.0` - `38.0`).
    pub chroma: f64,
    /// The CIE x chromaticity (illuminant C).
    pub x: f64,
    /// The CIE y chromaticity (illuminant C).
    pub y: f64,
    /// The true luminance factor `Y` (the published value scaled
    /// back by `0.975`).
    pub luminance: f64,
}

impl MunsellSample {
    /// The hue angle on the Munsell hue circle: `hue_number` steps of
    /// 9 degrees (`0` = 2.5R), wrapped into `0-360`.
    pub fn hue_angle(&self) -> Hue {
        Hue::new(self.hue_number * 9.0)
    }

    /// The sample as CIE XYZ tristimulus (illuminant C).
    pub fn to_xyz(&self) -> Xyz {
        Xyz::from_xyy(self.x, self.y, self.luminance)
    }

    /// The sample as sRGB color.
    ///
    /// The illuminant-C tristimulus is adapted to D65 with the
    /// Bradford transform; renotation colors outside the sRGB gamut
    /// are clamped channel-wise.
    pub fn to_color(&self) -> Color<u8> {
        Color::from(self.to_xyz().adapted(Xyz::WHITE_C, Xyz::WHITE_D65))
    }

    /// A neutral sample `N v/` with the renotation luminance of
    /// `value` - the illuminant-C chromaticity of the dataset at the
    /// Newhall (1943) value-function luminance.
    pub fn neutral(value: f64) -> Self {
        let (x, y, _) = Xyz::WHITE_C.to_xyy();
        Self {
            hue: "N",
            hue_number: 0.0,
            value,
            chroma: 0.0,
            x,
            y,
            luminance: value_luminance(value),
        }
    }

    /// The Munsell notation `H V/C`, e.g. `"5YR 7/4"` - or `N v` for
    /// neutral samples.
    pub fn notation(&self) -> String {
        if self.chroma <= 0.0 {
            format!("{}{}", self.hue, fmt_step(self.value))
        } else {
            format!("{} {}/{}", self.hue, fmt_step(self.value), fmt_step(self.chroma))
        }
    }

    /// Looks up a sample by notation parts (`"5YR"`, `7.0`, `4.0`).
    pub fn find(hue: &str, value: f64, chroma: f64) -> Option<&'static Self> {
        MUNSELL_SAMPLES
            .iter()
            .find(|sample| sample.hue == hue && sample.value == value && sample.chroma == chroma)
    }
}

/// The renotation luminance factor `Y` of a Munsell `value` - the
/// Newhall, Nickerson & Judd (1943) quintic value function, scaled by
/// `0.975` like the table entries. `V=5` yields `19.2757`.
fn value_luminance(value: f64) -> f64 {
    ((((0.0008404 * value - 0.021009) * value + 0.23951) * value - 0.23111) * value + 1.2219) * value * 0.975
}

fn fmt_step(value: f64) -> String {
    if value == value.trunc() {
        format!("{}", value as u64)
    } else {
        format!("{value}")
    }
}

