#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_table_holds_the_published_2734_samples() {
        assert_eq!(MUNSELL_SAMPLES.len(), 2734);
    }

    #[test]
    fn find_returns_the_lookup_of_notation_parts() {
        let sample = MunsellSample::find("5R", 5.0, 14.0).expect("5R 5/14");
        assert_eq!(sample.notation(), "5R 5/14");
    }

    #[test]
    fn hue_covers_the_full_circle() {
        assert_eq!(MUNSELL_SAMPLES[0].hue, "2.5R");
        assert_eq!(MUNSELL_SAMPLES[MUNSELL_SAMPLES.len() - 1].hue, "10RP");
    }

    #[test]
    fn a_deep_red_maps_into_the_srgb_gamut() {
        let sample = MunsellSample::find("5R", 4.0, 14.0).expect("5R 4/14");
        let color = sample.to_color();
        assert!(color.r > color.g && color.r > color.b);
    }

    #[test]
    fn neutral_uses_the_renotation_value_function() {
        let mid = MunsellSample::neutral(5.0);
        assert!((mid.luminance - 19.2757).abs() < 0.05, "N5 luminance, got {}", mid.luminance);
        assert_eq!(mid.notation(), "N5");
        let (x, y, _) = Xyz::WHITE_C.to_xyy();
        assert!((mid.x - x).abs() < 1e-12 && (mid.y - y).abs() < 1e-12);
        let color = mid.to_color();
        assert!((color.r as i16 - color.g as i16).abs() <= 2 && (color.g as i16 - color.b as i16).abs() <= 2);
    }
}
